class FundTransferSerializer(serializers.Serializer):
    source_vault_id = serializers.IntegerField()
    target_wallet_address = serializers.CharField(max_length=64)
    amount = serializers.DecimalField(max_digits=12, decimal_places=2)

    def validate_source_vault_id(self, value):
        user = self.context['request'].user
        vault = CryptoVault.objects.filter(id=value, owner=user).first()
        if not vault:
            raise serializers.ValidationError("Source vault not found or access denied.")
        if vault.is_frozen:
            raise serializers.ValidationError("Source vault is currently frozen.")
        return value
